package com.project7.localmanager;
import java.io.*;import java.util.*;
/** Persist original animation ACK only; f is the authority and a is its subset. */
final class WishAnimationPolicy {
 static LocalResourceEngine.Result apply(byte[]before,LocalResourceCatalog catalog,byte[]params)throws IOException{try{BaiyeTransactions.document(params);Set<String>keys=new HashSet<>(BsonLite.keys(params));keys.remove("_cbid_");WishCatalog.need(keys.equals(new HashSet<>(Arrays.asList("t","gi"))),"animation keys");if(BsonLite.keys(params).contains("_cbid_"))BaiyeTransactions.positive(BsonLite.numericValue(params,"_cbid_"));int t=BaiyeTransactions.positive(BsonLite.numericValue(params,"t"));MultiWishSpec spec=WishDrawPolicy.group(t);byte[]state=LocalDrawEngine.state(before,t);MultiWishState current=MultiWishState.read(spec,state,before,false);byte[]gi=BsonLite.arrayValue(params,"gi");WishCatalog.need(gi!=null,"animation pairs");List<byte[]>pairs=LocalResourceEngine.array(gi);WishCatalog.need(pairs.size()==BsonLite.keys(gi).size()&&pairs.size()<=spec.groups.size(),"animation pairs shape");Set<Integer>seen=new HashSet<>();for(byte[]pair:pairs){WishCatalog.need(BsonLite.keys(pair).size()==2,"animation pair");int gid=BaiyeTransactions.positive(BsonLite.numericValue(pair,"0"));WishCatalog.need(seen.add(gid)&&spec.groups.containsKey(gid),"animation gid");List<Integer>ids=BsonLite.intArrayValues(pair,"1");WishCatalog.need(ids!=null&&ids.size()<=spec.rowIds(gid).size()&&current.groups.get(gid).finished.containsAll(ids),"animation not finished");current.groups.get(gid).animated.addAll(ids);}LocalResourceEngine.Result result=new LocalResourceEngine.Result(before);LocalDrawEngine.saveState(result,current.save(state),t);result.add("syncLuckyDrawActivityData",BsonLite.document("t",t,"d",LocalDrawEngine.state(result.profile,t)));result.add("syncWishGroupInfo",BsonLite.document("t",t,"i",current.pairs()));return result;}catch(IOException e){throw e;}catch(Exception e){throw new IOException("祈愿动画状态未提交",e);}}
}
